function countBy(words: string[]): Record<string, number> {
  const counts: Record<string, number> = {}
  for (const word of words) {
    counts[word] = (counts[word] ?? 0) + 1   // missing key is undefined, so ?? supplies 0
  }
  return counts
}

console.log(JSON.stringify(countBy(['a', 'b', 'a'])))  // {"a":2,"b":1}
