solution:
type Json = null | boolean | number | string | Json[] | { [key: string]: Json }

function looseEqual(a: Json, b: Json): boolean {
  // null only loosely equals null (or undefined, which JSON cannot carry)
  if (a === null || b === null) return a === b
  // same type: plain strict equality (objects compare by identity)
  if (typeof a === typeof b) return a === b
  // a boolean side becomes a number first, then we compare again
  if (typeof a === 'boolean') return looseEqual(Number(a), b)
  if (typeof b === 'boolean') return looseEqual(a, Number(b))
  // number vs string: the string becomes a number
  if (typeof a === 'number' && typeof b === 'string') return a === Number(b)
  if (typeof a === 'string' && typeof b === 'number') return Number(a) === b
  // object vs primitive: ToPrimitive (arrays join, plain objects give "[object Object]")
  if (typeof a === 'object') return looseEqual(String(a), b)
  if (typeof b === 'object') return looseEqual(a, String(b))
  return false
}

Each call either answers directly or converts one side and recurses; every conversion moves towards a primitive, so the recursion is at most three levels deep (for example `[] == false` → `[] == 0` → `"" == 0` → `0 === 0`). Time is O(size of the array being stringified). The same-`typeof` check doubles as identity comparison for objects, which is exactly what `==` does when both sides are objects.

