interface Settings { retries: number; label: string; verbose: boolean }
type SettingsInput = { [K in keyof Settings]?: Settings[K] | null }

function resolveSettings(input: SettingsInput): Settings {
  return {
    retries: input.retries ?? 3,
    label: input.label ?? 'default',
    verbose: input.verbose ?? true,
  }
}

function toCents(amount: string): bigint {
  const match = /^(-?)(\d+)(?:\.(\d{1,2}))?$/.exec(amount)
  if (!match) throw new Error(`bad amount: ${amount}`)
  const [, sign, whole, fraction = ''] = match
  const cents = BigInt(whole) * 100n + BigInt(fraction.padEnd(2, '0'))
  return sign === '-' ? -cents : cents
}

function addMoney(amounts: string[]): string {
  const total = amounts.reduce((sum, amount) => sum + toCents(amount), 0n)
  const negative = total < 0n
  const abs = negative ? -total : total
  const cents = (abs % 100n).toString().padStart(2, '0')
  return `${negative ? '-' : ''}${abs / 100n}.${cents}`
}

